#include <iostream>
#include <vector>
#include <queue>
using namespace std;

vector<int> adj[100];
bool visited[100];
int dist[100];

void bfs(int start) {
    queue<int> q;
    q.push(start);
    visited[start] = true;
    dist[start] = 0;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    bfs(1);
    for (int i = 1; i <= n; i++)
        cout << i << ": " << dist[i] << endl;
    return 0;
}

#include <iostream>
using namespace std;

int n, m;
char grid[100][100];
bool visited[100][100];
int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void dfs(int x, int y) {
    visited[x][y] = true;
    for (int d = 0; d < 4; d++) {
        int nx = x + dx[d], ny = y + dy[d];
        if (nx >= 0 && nx < n && ny >= 0 && ny < m
            && !visited[nx][ny] && grid[nx][ny] == '.') {
            dfs(nx, ny);
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            cin >> grid[i][j];
    int cnt = 0;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (grid[i][j] == '.' && !visited[i][j]) {
                dfs(i, j);
                cnt++;
            }
    cout << cnt << endl;
    return 0;
}

units.explanation:
回溯法是「试错」的搜索方法：尝试每种可能，发现走不通就回退（撤销选择），换另一条路。

回溯框架：
void backtrack(状态) {
    if (满足结束条件) { 记录答案; return; }
    for (每个候选选择) {
        做选择;
        backtrack(新状态);
        撤销选择;  // 回溯
    }
}

剪枝：在搜索过程中提前判断某些分支不可能产生正确答案，直接跳过。

常见剪枝：
- 可行性剪枝：当前状态已经不满足约束
- 最优性剪枝：当前方案不可能比已知最优更好
- 对称性剪枝：利用对称性减少重复

