#include <iostream>
#include <vector>
using namespace std;

int n;
vector<int> path;

void backtrack(int used) {
    if (path.size() == n) {
        for (int x : path) cout << x << " ";
        cout << endl;
        return;
    }
    for (int i = 1; i <= n; i++) {
        if (used & (1 << i)) continue;
        path.push_back(i);
        backtrack(used | (1 << i));
        path.pop_back();
    }
}

int main() {
    cin >> n;
    backtrack(0);
    return 0;
}
